/**
 * @file src/ui/floatingText.ts
 * showFloatingText — Floating combat text
 */

export type FloatingTextPayload = { text: string; html?: string };

/** Délai entre chaque popup d'une rafale multi-coups (ms). */
export const BURST_ANIMATION_DELAY_MS = 95;

export interface BurstPopupOffsets {
    offsetXPercent: number;
    bottomPx: number;
    animationDelayMs: number;
}

/**
 * Positions légèrement décalées pour simuler une rafale (multi-coups).
 * hitIndex === 0 : dispersion normale (coup simple ou 1er coup de rafale).
 */
export function computeBurstPopupOffsets(
    hitIndex: number,
    random: () => number = Math.random,
): BurstPopupOffsets {
    const isBurst = hitIndex > 0;
    const burstFanX = isBurst
        ? ((hitIndex % 2 === 0 ? -1 : 1) * Math.ceil(hitIndex / 2) * 3)
        : 0;
    const offsetXPercent = isBurst
        ? burstFanX + (random() * 4 - 2)
        : (random() * 40 - 20);
    const bottomPx = (isBurst ? 42 : 40)
        + random() * (isBurst ? 10 : 20)
        + hitIndex * 4;
    const animationDelayMs = isBurst ? hitIndex * BURST_ANIMATION_DELAY_MS : 0;
    return { offsetXPercent, bottomPx, animationDelayMs };
}

/**
 * Affiche un texte flottant animé (dégâts, soins, etc.)
 */
export function showFloatingText(
    text: string | FloatingTextPayload,
    targetContainer: HTMLElement | null | undefined,
    type = '',
    isCritical = false,
    hitIndex = 0,
): void {
    if (!targetContainer) return;

    const textElement = document.createElement('div');
    const payload = (text && typeof text === 'object' && !Array.isArray(text)) ? text : null;
    const rawText = payload ? String(payload.text || '') : (typeof text === 'string' ? text : '');
    const rawHtml = payload && typeof payload.html === 'string' ? payload.html : '';

    const critClass = isCritical ? ' ft-crit' : '';
    textElement.className = `floating-text ${type}${critClass}`;

    let content = rawText;
    if (!payload) {
        if (isCritical) content = `${rawText}`;
        else if (type.includes('heal')) content = `+${rawText}`;
    }

    if (rawHtml) textElement.innerHTML = rawHtml;
    else textElement.textContent = content;

    let animationDelayMs = 0;

    if (type.includes('ft-from-rj')) {
        textElement.style.left = '22%';
        textElement.style.bottom = '0';
        textElement.style.transform = 'translateX(-50%)';
    } else if (type.includes('ft-on-action-row')) {
        textElement.style.left = '50%';
        textElement.style.top = '50%';
        textElement.style.bottom = 'auto';
    } else {
        const burst = computeBurstPopupOffsets(hitIndex);
        animationDelayMs = burst.animationDelayMs;
        textElement.style.left = `calc(50% + ${burst.offsetXPercent}%)`;
        textElement.style.bottom = `${burst.bottomPx}px`;
        if (animationDelayMs > 0) {
            textElement.style.animationDelay = `${animationDelayMs}ms`;
        }
    }

    targetContainer.appendChild(textElement);

    const baseDurationMs = type.includes('ft-on-action-row') ? 2100 : 1000;
    setTimeout(() => {
        if (textElement.parentElement) {
            textElement.parentElement.removeChild(textElement);
        }
    }, baseDurationMs + animationDelayMs);
}
